<?php declare(strict_types=1); use App\Core\Csrf; ob_start(); ?><section class="admin-page-head"><div><p class="admin-eyebrow">Opt-in explícito</p><h2>Campanhas</h2><p>O enfileiramento não envia e-mail; a preferência é conferida novamente antes da entrega.</p></div><a class="admin-button" href="/admin/campanhas/nova">Nova campanha</a></section><section class="admin-panel"><div class="admin-table-wrap"><table><thead><tr><th>Nome</th><th>Segmento</th><th>Status</th><th>Público</th><th>Ações</th></tr></thead><tbody><?php foreach($campaigns as $c): ?><tr><td><?= e((string)$c['name']) ?></td><td><?= e((string)$c['segment']) ?></td><td><?= e((string)$c['status']) ?></td><td><?= (int)$c['recipients'] ?></td><td><a href="/admin/campanhas/<?= (int)$c['id'] ?>/editar">Editar</a> · <a href="/admin/campanhas/<?= (int)$c['id'] ?>/historico">Histórico</a><?php if(in_array($c['status'],['draft','scheduled','processing','completed'],true)): ?><form method="post" action="/admin/campanhas/<?= (int)$c['id'] ?>/cancelar"><input type="hidden" name="_token" value="<?= e(Csrf::token()) ?>"><button class="admin-button admin-button-small">Cancelar</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if($campaigns===[]): ?><tr><td colspan="5">Nenhuma campanha criada.</td></tr><?php endif; ?></tbody></table></div></section><?php $content=(string)ob_get_clean();require __DIR__.'/../layouts/admin.php';
